// --- inputs -----------------------------------------------------------------
let clinic_cost_code = ZT.getVariableValue("clinic_cost_code", "");

// --- outputs ----------------------------------------------------------------
// The Ivy Azure insurance object takes its cost code from new_cost_code.
ZT.setFormData("new_cost_code", clinic_cost_code);

52.content:
// --- inputs -----------------------------------------------------------------
// region comes from the SharePoint clinic info (tree 787613344). insurance_list is the
// clinic's accepted list from the Ivy Azure object; a clinic with no list returns none.
let region = ZT.getVariableValue("region", "");
let accepted = actions.alias_35?.insurance_list || [];

// --- build the dropdown options ---------------------------------------------
let insurance_list = accepted.map(x => ({ name: x, value: x }));

// --- staged rollout: only these regions see the dropdown ---------------------
// Every other region keeps the free-text insurance field only. Add a region here to extend.
const INSURANCE_DROPDOWN_REGIONS = ["brooklyn", "north charlotte", "south charlotte"];
let is_display_insurance_dropdown =
  INSURANCE_DROPDOWN_REGIONS.includes(String(region).trim().toLowerCase()) && insurance_list.length > 0;

// --- outputs ----------------------------------------------------------------
ZT.setTransformData("insurance_list", insurance_list);
ZT.setFormData("is_display_insurance_dropdown", is_display_insurance_dropdown);
